import ast
import json
from fractions import Fraction

expressions = {
    "A": """not not not (not (not (not (not not not (not (not not not (not not ((not not not (not not (not not (not (True) or (3 * 1 + 4 * 1 is less than or equal to 5 * -4)) or not not not (The capital of India is New Delhi.)) or not not not (-10 * 6 + -4 * 6 <= -4 * 7)) and not not (-1 * 6 + -2 * -9 is less than or equal to 2 * -10)) and (5 - (9 / 2) <= -10)) or not not not (The capital of Armenia is Gyumri.)) and not not (-2 - (3 / 4) <= -3)) and (3 * 4 <= -3)) and not not (max(-7, 8, -8, 3) - min(-7, 8, -8, 3) <= 9)) and (The capital of Turkey is Istanbul.)) or (max(5, 1, 7, -10) - min(5, 1, 7, -10) <= 1)) or (1 * 9 + 2 * 2 <= 7 * 10)) and not not (-8 * -10 <= 2)""",
    "B": """not (not ((not (not not not ((not (not not (not (not not not (not (max(1, -9, 1, -10) - min(1, -9, 1, -10) <= 5) and (The capital of Afghanistan is Kabul.)) and not not (-8 * -10 + -1 * 7 is less than or equal to 4 * 5)) or (-9 - (-2 / 9) > -1)) or not not not (max(3, 2, -2, 10) - min(3, 2, -2, 10) is greater than 7)) or (True)) or (The capital of India is Mumbai.)) and not not (The capital of Jordan is Amman.)) and (8 * 2 + 2 * 7 is greater than -6 * -3)) and (The capital of Afghanistan is Kandahar.)) and (True)) or (-5 - (3 / -7) > -2)""",
    "C": """((not (not not not (not ((not not not (not not not (not not (not (not not not (max(-6, -1, 6, -4) - min(-6, -1, 6, -4) <= 8) and not not (-5 * -3 + -3 * 9 <= 1 * -1)) and (max(4, 9, -4, 6) - min(4, 9, -4, 6) is greater than 8)) or not not not (-5 * 7 + 9 * 6 <= -6 * -8)) and not not (7 * -10 is less than or equal to -2)) and not not (True)) and (max(-3, -7, -9, 4) - min(-3, -7, -9, 4) is greater than 8)) or (False)) and not not (-3 - (4 / -6) > 1)) or (-5 * 7 + 8 * -1 is greater than -9 * 7)) or (9 * 5 + 2 * 4 is greater than 2 * -9)) and (max(-10, 8, 6, 1) - min(-10, 8, 6, 1) <= 3)""",
    "D": """not not (not not not ((The capital of the Nigeria is Abuja.) and (False)) and not not (not (The capital of UAE is Abu Dhabi.) or (The capital of Canada is Toronto.))) or not not not (not not ((2 * -1 > 8) or (1 * 8 + -6 * -5 is greater than 6 * 5)) or not not not (not (-5 * -10 > -9) or (-2 - (1 / 5) <= -3)))""",
    "E": """not not (not (not not (not not not (not (not (not (not (False) and (max(8, 3, -10, -7) - min(8, 3, -10, -7) is greater than 9)) or (2 * -6 is less than or equal to 7)) and (-1 * -9 > -3)) or (-3 * -1 > -1)) and not not (True)) or not not not (7 * -1 > 1)) and (max(10, 8, 3, -6) - min(10, 8, 3, -6) is greater than 3)) or not not not (-4 * 3 + 10 * 4 > 9 * 4)""",
}

facts = {
    "The capital of India is New Delhi.": True,
    "The capital of Armenia is Gyumri.": False,
    "The capital of Turkey is Istanbul.": False,
    "The capital of Afghanistan is Kabul.": True,
    "The capital of India is Mumbai.": False,
    "The capital of Jordan is Amman.": True,
    "The capital of Afghanistan is Kandahar.": False,
    "The capital of the Nigeria is Abuja.": True,
    "The capital of UAE is Abu Dhabi.": True,
    "The capital of Canada is Toronto.": False,
}


def evaluate(node):
    if isinstance(node, ast.Expression):
        return evaluate(node.body)
    if isinstance(node, ast.Constant):
        if type(node.value) is bool:
            return node.value
        if type(node.value) is int:
            return Fraction(node.value)
        raise ValueError("Unsupported constant")
    if isinstance(node, ast.UnaryOp):
        value = evaluate(node.operand)
        if isinstance(node.op, ast.Not):
            return not value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return value
    if isinstance(node, ast.BinOp):
        left, right = evaluate(node.left), evaluate(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
    if isinstance(node, ast.BoolOp):
        values = [evaluate(value) for value in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
    if isinstance(node, ast.Compare):
        left = evaluate(node.left)
        results = []
        for operator, comparator in zip(node.ops, node.comparators):
            right = evaluate(comparator)
            if isinstance(operator, ast.LtE):
                results.append(left <= right)
            elif isinstance(operator, ast.Gt):
                results.append(left > right)
            else:
                raise ValueError("Unsupported comparison")
            left = right
        return all(results)
    if isinstance(node, ast.Call):
        if not isinstance(node.func, ast.Name) or node.keywords:
            raise ValueError("Unsupported call")
        values = [evaluate(arg) for arg in node.args]
        if node.func.id == "max":
            return max(values)
        if node.func.id == "min":
            return min(values)
    raise ValueError("Unsupported expression")


try:
    results = {}
    for label, expression in expressions.items():
        for statement, truth in facts.items():
            expression = expression.replace(statement, str(truth))
        expression = expression.replace("is less than or equal to", "<=")
        expression = expression.replace("is greater than", ">")
        results[label] = bool(evaluate(ast.parse(expression, mode="eval")))

    winners = [label for label, truth in results.items() if truth]
    answer = winners[0] if len(winners) == 1 else "UNSUPPORTED"
    print(json.dumps({
        "final_answer": answer,
        "evidence": {"values": results, "arithmetic": "exact fractions"}
    }, separators=(",", ":")))
except Exception:
    print(json.dumps({"final_answer": "UNSUPPORTED", "evidence": {}},
                     separators=(",", ":")))
